-- Mod-authored Congress splash painting descriptions, es_ES overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "No hay descripción para esta imagen."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Una asamblea en sesión, vista desde el fondo de la sala por encima de las cabezas del público. Al frente, los delegados están sentados en torno a una larga mesa cubierta de rojo sobre una tarima enmoquetada, con una hoja de papel blanco ante cada lugar. Una figura con túnica blanca y tocado blanco está de pie en la cabecera de la mesa para dirigirse a la sala, con un hombre de barba oscura a su lado. El público los escucha desde filas de sillas de madera, turbantes y gorros y cabezas descubiertas todos juntos. Más mirones observan desde entre pálidas columnas a lo largo de la pared derecha."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Una gran noria asoma por la parte superior del encuadre a la derecha, con los vagones cerrados para pasajeros colgando de su aro. Su base desciende por detrás de un gran arco de hierro verde remachado, que se extiende ante una pálida pared con las letras FERRIS WHEEL. Los visitantes de la Feria Mundial cruzan el amplio paseo polvoriento: mujeres con vestidos largos, hombres con abrigos y sombreros bombines y de copa. Bajos pabellones de feria con carteles pintados se alinean a la izquierda, donde al fondo se alza una sala blanca con cúpula bajo un pálido cielo azul."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Los primeros pasos de una carrera: cuatro corredores arrancan con fuerza desde la línea de salida, cabeza gacha, sobre una pista oscura que traza una curva a lo largo del primer plano. Detrás de ellos a la izquierda, el juez de salida está de pie con un largo abrigo blanco, la pistola alzada y aún humeante. Las gradas repletas llenan todo el fondo, la muchedumbre esbozada como manchas de color. Tribunas de escalera blancas y altos postes bordean la pista a la derecha, y el verde del campo interior se extiende más allá de ellos."
